# Tierwohl – Schweinehaltung (o6_22): free-range husbandry on unpaved areas.
package oepul.o6_22

freiland_groups := {i: g | some i, g in participating_groups; freiland_kept(g)}

# Rule: O622-FREE-01 (stocking limit per water-law permit, otherwise 4 GVE/ha)
freiland_stocking_limit(g) := pasture(g).water_permit_max_gve_per_ha if {
	is_number(object.get(pasture(g), "water_permit_max_gve_per_ha", null))
} else := params.freiland_default_max_gve_per_ha

# Rule: O622-FREE-01 (with paddock rotation the whole area available over the holding period counts)
freiland_area_ha(g) := pasture(g).rotation_total_area_ha if {
	is_number(object.get(pasture(g), "rotation_total_area_ha", null))
	pasture(g).rotation_total_area_ha > 0
} else := pasture(g).pasture_area_ha

freiland_stocking_gve_per_ha(g) := r2(present_gve(g) / freiland_area_ha(g)) if freiland_area_ha(g) > 0

# Rule: O622-FREE-04 (litter in the shelter not required for empty and pregnant sows)
shelter_litter_required(g) if not is_sow_group(g)

shelter_litter_required(g) if {
	is_sow_group(g)
	object.get(welfare(g), "sow_phase", null) != "empty_or_pregnant"
}

# Rule: O622-FREE-01
group_issues contains {"group": i, "rule_id": "O622-FREE-01", "reason": "freiland_stocking_density_exceeded"} if {
	some i, g in freiland_groups
	freiland_stocking_gve_per_ha(g) > freiland_stocking_limit(g)
}

# Rule: O622-FREE-08 (continuous use of the same unpaved area max. one year)
group_issues contains {"group": i, "rule_id": "O622-FREE-08", "reason": "freiland_continuous_use_over_one_year"} if {
	some i, g in freiland_groups
	pasture(g).continuous_use_months > params.freiland_max_continuous_use_months
}

# Rule: O622-FREE-02 (double fence or founded, tight enclosure against wild boar contact)
group_issues contains {"group": i, "rule_id": "O622-FREE-02", "reason": "freiland_enclosure_insufficient"} if {
	some i, g in freiland_groups
	pasture(g).double_fence_or_solid_enclosure == false
}

# Rule: O622-FREE-03 (feeding place and drinker separated)
group_issues contains {"group": i, "rule_id": "O622-FREE-03", "reason": "freiland_feed_and_water_not_separated"} if {
	some i, g in freiland_groups
	pasture(g).feeding_and_watering_separated == false
}

# Rule: O622-FREE-03 (paved ground or regular relocation)
group_issues contains {"group": i, "rule_id": "O622-FREE-03", "reason": "freiland_feed_and_water_not_paved_or_relocated"} if {
	some i, g in freiland_groups
	pasture(g).feeding_and_watering_paved_or_relocated == false
}

# Rule: O622-FREE-03 (roofed feeding place)
group_issues contains {"group": i, "rule_id": "O622-FREE-03", "reason": "freiland_feeding_place_not_roofed"} if {
	some i, g in freiland_groups
	pasture(g).feeding_place_roofed == false
}

# Rule: O622-FREE-04 (roofed, three-sided closed shelter in which all animals can lie)
group_issues contains {"group": i, "rule_id": "O622-FREE-04", "reason": "freiland_shelter_insufficient"} if {
	some i, g in freiland_groups
	some field in ["shelter_roofed", "shelter_three_sided_closed", "shelter_all_animals_lie_simultaneously"]
	pasture(g)[field] == false
}

# Rule: O622-FREE-04 (littered shelter)
group_issues contains {"group": i, "rule_id": "O622-FREE-04", "reason": "freiland_shelter_not_littered"} if {
	some i, g in freiland_groups
	shelter_litter_required(g)
	pasture(g).shelter_littered == false
}

# Rule: O622-FREE-04 / O622-DEF-STALL-04 (farrowing huts for breeding sows)
group_issues contains {"group": i, "rule_id": "O622-FREE-04", "reason": "freiland_farrowing_huts_missing"} if {
	some i, g in freiland_groups
	is_sow_group(g)
	object.get(welfare(g), "sow_phase", null) != "empty_or_pregnant"
	pasture(g).farrowing_huts_available == false
}

# Rule: O622-FREE-07 (wild boars are not eligible and must be deregistered)
group_issues contains {"group": i, "rule_id": "O622-FREE-07", "reason": "wild_boar_not_eligible"} if {
	some i, g in participating_groups
	g.is_wild_boar == true
}

# Rule: O622-FREE-06 (continuous free-range documentation per plot)
violations contains {
	"rule_id": "O622-FREE-06",
	"severity": "obligation",
	"message": sprintf("Group %v: free-range documentation (start/end of grazing period and animals per plot) incomplete", [i]),
} if {
	some i, g in freiland_groups
	pasture(g).documentation_per_plot_complete == false
}

# Rule: O622-APP-08 (unpaved free-range areas declared as 'Sonstige Acker-/Grünlandflächen')
violations contains {
	"rule_id": "O622-APP-08",
	"severity": "obligation",
	"message": sprintf("Group %v: unpaved free-range area must be declared with land-use type 'Sonstige Ackerflächen' or 'Sonstige Grünlandflächen'", [i]),
} if {
	some i, g in freiland_groups
	pasture(g).unpaved_area_declared_as_other_land == false
}

missing_inputs contains sprintf("livestock.species_groups[%v].housing.pasture.pasture_area_ha", [i]) if {
	some i, g in freiland_groups
	not is_number(object.get(pasture(g), "pasture_area_ha", null))
	not is_number(object.get(pasture(g), "rotation_total_area_ha", null))
}

# Tierwohl – Schweinehaltung (o6_22): general ÖPUL 2023 participation conditions
# (Allgemeine Teilnahmebedingungen / Sonderrichtlinie Allgemeiner Teil) as far
# as they apply to this one-year, animal-related measure.
package oepul.o6_22

applicant := object.get(input, ["farm", "applicant"], {})

applicant_type_codes := {row.code | some row in general.applicant_types}

# Rule: O622-GEN-APPL-03 (public bodies only for the listed measures; o6_22 is not listed)
public_body_allowed(measure, _) if {
	some row in general.public_body_exempt_measures
	row.measure == measure
	object.get(row, "from_year", null) == null
	object.get(row, "to_year", null) == null
}

public_body_allowed(measure, y) if {
	some row in general.public_body_exempt_measures
	row.measure == measure
	row.to_year != null
	y <= row.to_year
}

public_body_allowed(measure, y) if {
	some row in general.public_body_exempt_measures
	row.measure == measure
	row.from_year != null
	y >= row.from_year
}

# Rule: O622-GEN-APPL-01 (eligible legal forms)
applicant_issues contains "legal_form_not_eligible" if {
	applicant.legal_form
	not applicant.legal_form in applicant_type_codes
}

# Rule: O622-GEN-APPL-03 (public bodies / >25 % public participation excluded for o6_22)
applicant_issues contains "public_body_excluded" if {
	applicant.is_public_body == true
	not public_body_allowed(params.measure_code, year)
}

applicant_issues contains "public_body_share_above_25_percent" if {
	applicant.public_body_share_percent > 25
	not public_body_allowed(params.measure_code, year)
}

# Rule: O622-GEN-APPL-02 (active farmer, agricultural activity, own name and account)
applicant_issues contains "not_active_farmer" if applicant.is_active_farmer == false

applicant_issues contains "no_agricultural_activity" if applicant.carries_out_agricultural_activity == false

applicant_issues contains "farm_not_managed_in_own_name_and_account" if applicant.farm_managed_in_own_name_and_account == false

applicant_eligible if count(applicant_issues) == 0

violations contains {
	"rule_id": "O622-GEN-APPL-01",
	"severity": "access_condition",
	"message": sprintf("Applicant not eligible: %v", [reason]),
} if {
	some reason in applicant_issues
}

# Rule: O622-GEN-MINSIZE-01 / O622-GEN-MINSIZE-02 (minimum farm size only in the first ÖPUL year)
min_farm_size_required if oepul_farm.first_participation_year == year

min_farm_size_met if object.get(input, ["land", "protected_cultivation_area_ha"], 0) >= general.min_farm_size_first_year.protected_cultivation_min_ha

min_farm_size_met if object.get(input, ["land", "total_area_ha"], 0) >= general.min_farm_size_first_year.agricultural_area_min_ha

min_farm_size_ok if not min_farm_size_required

min_farm_size_ok if min_farm_size_met

violations contains {
	"rule_id": "O622-GEN-MINSIZE-01",
	"severity": "access_condition",
	"message": "First ÖPUL year: at least 0.50 ha protected cultivation or 1.50 ha agricultural area required",
} if {
	not min_farm_size_ok
}

# Rule: O622-GEN-CONTROL-01 (refusal of on-the-spot controls: application rejected)
control_refused if oepul_farm.control_refused == true

violations contains {
	"rule_id": "O622-GEN-CONTROL-01",
	"severity": "application_rejected",
	"message": "On-the-spot control refused or prevented: application rejected, no premium for the current year, contracts terminated",
} if {
	control_refused
}

# Rule: O622-GEN-TAKEOVER-01 (takeover only in individual cases: dissolution, division or merger;
# animals and areas from the same previous farm)
takeover := object.get(app, "takeover", {})

takeover_reason_codes := {row.code | some row in general.takeover_allowed_reasons}

takeover_single_case_only(measure) if {
	some row in general.takeover_single_case_only
	row.measure == measure
}

violations contains {
	"rule_id": "O622-GEN-TAKEOVER-01",
	"severity": "application_invalid",
	"message": "Takeover of o6_22 only possible in individual cases of farm dissolution, division or merger",
} if {
	takeover.is_takeover == true
	takeover_single_case_only(params.measure_code)
	not takeover.reason in takeover_reason_codes
}

violations contains {
	"rule_id": "O622-GEN-TAKEOVER-01",
	"severity": "application_invalid",
	"message": "Takeover of an animal-related measure requires animals and areas from the same previous farm",
} if {
	takeover.is_takeover == true
	takeover.animals_and_areas_from_same_previous_farm == false
}

# Rule: O622-GEN-SWITCH-01 (measure switch only along the listed pairs; o6_22 is not listed)
switch_allowed(from_label, to_label) if {
	some row in general.measure_switch_matrix
	row.from == from_label
	to_label in row.to
}

# Rule: O622-GEN-COMB-01 (combination allowed unless excluded; no exclusion lists o6_22)
combination_excluded(a, b) if {
	some pair in general.farm_level_excluded_combinations
	a in pair.group_a
	b in pair.group_b
}

combination_excluded(a, b) if {
	some pair in general.farm_level_excluded_combinations
	b in pair.group_a
	a in pair.group_b
}

combination_allowed(a, b) if not combination_excluded(a, b)

# Rule: O622-GEN-MOD-01 (Betriebsgrößenmodulation by total farm area)
tier_upper(t, area) := t.to_ha_inclusive if t.to_ha_inclusive != null

else := area

tier_portion(t, area) := max([0, min([area, tier_upper(t, area)]) - t.from_ha_exclusive])

modulation_factor(area) := 1 if area <= 0

modulation_factor(area) := sum([weighted |
	some t in general.modulation_tiers
	weighted := tier_portion(t, area) * t.payout_factor
]) / area if {
	area > 0
}

# Rule: O622-GEN-SANCTION-01 (sanction stages; from 2027 1 % retention instead of a warning)
sanction_reduction_percent(stage, y) := row.reduction_percent_from_2027 if {
	some row in general.sanction_stages
	row.stage == stage
	y >= 2027
}

sanction_reduction_percent(stage, y) := row.reduction_percent if {
	some row in general.sanction_stages
	row.stage == stage
	y < 2027
}

# Rule: O622-GEN-SANCTION-01 (exclusion after two 100 % reductions within the contract period)
exclusion_triggered(full_reductions_in_contract_period) if full_reductions_in_contract_period >= 2

# Rule: O622-GEN-PAY-02 (payment may be waived if the amount does not exceed EUR 50)
payout_may_be_waived(amount) if amount <= general.payment.min_payout_eur_exclusive

# Rule: O622-GEN-PAY-01 (advance payment max. 75 %)
max_advance_payment(amount) := r2((amount * general.payment.advance_payment_max_percent) / 100)

# Rule: O622-GEN-PAY-01 (payout by 30 June of the following year)
payout_deadline(y) := sprintf("%d-%s", [y + 1, general.payment.payout_deadline_month_day_following_year])

# Tierwohl – Schweinehaltung (o6_22): deregistration duty, animal health service,
# stall sketch/occupancy plan, VIS reporting.
package oepul.o6_22

noncompliant_groups := {i | some issue in group_issues; i := issue.group}

# Rule: O622-REPORT-01 / O622-FAT-ALL-01 / O622-FAT-ALL-02 (all animals of the category; not kept according to the conditions must be deregistered)
required_deregistration_count[c] := n if {
	some c in active_categories
	n := sum([group_count(category_groups[i]) |
		some i in noncompliant_groups
		category_of(category_groups[i]) == c
	])
}

violations contains {
	"rule_id": "O622-REPORT-01",
	"severity": "obligation",
	"message": sprintf("Category %v: %v animals (annual average) do not meet the conditions but only %v were deregistered", [c, n, deregistered_count(c)]),
} if {
	some c, n in required_deregistration_count
	n > 0
	deregistered_count(c) < n
}

# Rule: O622-REPORT-01 (deregistration must be made immediately)
violations contains {
	"rule_id": "O622-REPORT-01",
	"severity": "obligation",
	"message": sprintf("Deregistration for category %v was not notified immediately", [d.measure_category]),
} if {
	some d in object.get(app, "deregistrations", [])
	d.notified_immediately == false
}

# Rule: O622-TGD-01 (GVE of premium-eligible pigs held on the farm; wild boars excluded)
farm_eligible_pig_gve := r2(sum([group_gve(g) |
	some g in category_groups
	object.get(g, "is_wild_boar", false) != true
]))

tgd_required if farm_eligible_pig_gve > params.tgd_gve_threshold_exclusive

# Rule: O622-TGD-02 (2023: participation from 15 April 2023 suffices)
tgd_required_from := params.tgd_2023_participation_start if year == 2023

else := year_start(year)

tgd_ok if {
	t := app.animal_health_service
	t.participating == true
	t.from <= tgd_required_from
	t.to >= year_end(year)
}

# Rule: O622-TGD-01
violations contains {
	"rule_id": "O622-TGD-01",
	"severity": "obligation",
	"message": sprintf("%v GVE premium-eligible pigs (> %v GVE): participation in a recognised pig health service (TGD) for the whole year is required", [farm_eligible_pig_gve, params.tgd_gve_threshold_exclusive]),
} if {
	measure_applied
	tgd_required
	not tgd_ok
}

# Rule: O622-DOC-SKETCH-01 / O622-DOC-SKETCH-04 (stall sketch and occupancy plan up to and including 2024)
stall_sketch_required if {
	year <= params.stall_sketch_required_until_year
	count(stall_groups) > 0
}

violations contains {
	"rule_id": "O622-DOC-SKETCH-01",
	"severity": "obligation",
	"message": "Stall sketch and occupancy plan (maximum occupancy) per category and compartment must be available on the farm",
} if {
	stall_sketch_required
	object.get(app, "stall_sketch_and_occupancy_plan_available", false) != true
}

# Rule: O622-VIS-01 (VIS reporting of animal movements under TKZVO 2009)
violations contains {
	"rule_id": "O622-VIS-01",
	"severity": "legal_obligation",
	"message": "Pig movements (arrivals and departures of live animals) must be reported to the VIS",
} if {
	count(listed_pig_groups) > 0
	object.get(app, "vis_reporting_complete", null) == false
}

# Rule: O622-GEN-LOC-01 (animals kept outside Austria must not be listed)
violations contains {
	"rule_id": "O622-GEN-LOC-01",
	"severity": "declaration",
	"message": sprintf("Group %v is kept outside Austria and must not be listed or counted", [i]),
} if {
	some i, g in object.get(input, ["livestock", "species_groups"], [])
	g.species == "pigs"
	g.kept_in_austria == false
}

# Tierwohl – Schweinehaltung (o6_22): applications, contract validity, entry
# deadlines, withdrawals, participating GVE and minimum participation.
package oepul.o6_22

# Rule: O622-APP-01 / O622-GEN-APP-01 (Maßnahmenantrag by 31 December before contract start)
application_deadline(first_commitment_year) := year_end(first_commitment_year - 1)

application_timely(a) if a.applied_on <= application_deadline(a.first_commitment_year)

# Rule: O622-APP-02 / O622-GEN-ONEYEAR-01 (last entry into categories: commitment year 2027)
category_application_valid(a) if {
	a.measure_category in object.keys(measure_categories)
	a.first_commitment_year >= params.first_programme_year
	a.first_commitment_year <= params.last_entry_commitment_year_categories
	application_timely(a)
}

# Rule: O622-APP-03 / O622-GEN-SUPP-APP-01 (supplements via Maßnahmenantrag; last entry commitment year 2028)
supplement_application_valid(s) if {
	s.first_commitment_year >= params.first_programme_year
	s.first_commitment_year <= params.last_entry_commitment_year_supplements
	application_timely(s)
	supplement_start_allowed(s)
	supplement_scope_allowed(s)
}

# Rule: O622-SUP-COMP-01 (Festmistkompostierung only from application year 2025)
supplement_start_allowed(s) if s.supplement in {"unkupiert", "gvo_frei_eiweiss"}

supplement_start_allowed(s) if {
	s.supplement == "festmistkompostierung"
	s.first_commitment_year >= params.festmist_supplement_first_year
}

# Rule: O622-SUP-UNK-03 (undocked supplement only for Ferkel and Jung-/Mastschweine)
supplement_scope_allowed(s) if s.supplement in {"gvo_frei_eiweiss", "festmistkompostierung"}

supplement_scope_allowed(s) if {
	s.supplement == "unkupiert"
	measure_categories[s.measure_category].undocked_supplement_available == true
}

withdrawals := object.get(app, "withdrawals", [])

withdrawal_covers_category(w, _) if w.scope == "measure"

withdrawal_covers_category(w, c) if {
	w.scope == "category"
	w.measure_category == c
}

withdrawal_covers_supplement(w, _) if w.scope == "measure"

withdrawal_covers_supplement(w, s) if {
	w.scope == "supplement"
	w.supplement == s.supplement
	object.get(w, "measure_category", null) == null
}

withdrawal_covers_supplement(w, s) if {
	w.scope == "supplement"
	w.supplement == s.supplement
	w.measure_category == object.get(s, "measure_category", null)
}

# Rule: O622-EXIT-01 / O622-EXIT-02 / O622-GEN-EXIT-01 / O622-GEN-REENTRY-01
# A withdrawal notified during a calendar year makes the measure (category,
# supplement) invalid for that whole year and ends the contract thereafter.
category_application_terminated(a) if {
	some w in withdrawals
	withdrawal_covers_category(w, a.measure_category)
	year_of(w.notified_on) >= a.first_commitment_year
	year_of(w.notified_on) <= year
}

supplement_application_terminated(s) if {
	some w in withdrawals
	withdrawal_covers_supplement(w, s)
	year_of(w.notified_on) >= s.first_commitment_year
	year_of(w.notified_on) <= year
}

# Rule: O622-CONTRACT-02 (automatic extension of categories unless withdrawn)
active_categories contains a.measure_category if {
	some a in object.get(app, "category_applications", [])
	category_application_valid(a)
	a.first_commitment_year <= year
	not category_application_terminated(a)
}

# Rule: O622-CONTRACT-02 (automatic extension of supplements unless withdrawn)
active_supplement_keys contains {"supplement": s.supplement, "measure_category": object.get(s, "measure_category", null)} if {
	some s in object.get(app, "supplement_applications", [])
	supplement_application_valid(s)
	s.first_commitment_year <= year
	not supplement_application_terminated(s)
}

# Rule: O622-SUP-UNK-01 / O622-SUP-GVO-01 / O622-SUP-COMP-01 (supplement applies per participating category)
supplement_active_for(sup, c) if {
	some k in active_supplement_keys
	k.supplement == sup
	k.measure_category == c
	c in active_categories
}

supplement_active_for(sup, c) if {
	some k in active_supplement_keys
	k.supplement == sup
	sup != "unkupiert"
	k.measure_category == null
	c in active_categories
}

# Invalid applications are reported so that they are not silently ignored.
violations contains {
	"rule_id": "O622-APP-01",
	"severity": "application_invalid",
	"message": sprintf("Category application %v is late, outside the entry window or unknown", [a.measure_category]),
} if {
	some a in object.get(app, "category_applications", [])
	not category_application_valid(a)
}

violations contains {
	"rule_id": "O622-APP-03",
	"severity": "application_invalid",
	"message": sprintf("Supplement application %v is late, outside the entry window or not offered for this category", [s.supplement]),
} if {
	some s in object.get(app, "supplement_applications", [])
	not supplement_application_valid(s)
}

participating_groups := {i: g |
	some i, g in category_groups
	category_of(g) in active_categories
}

category_head_count(c) := sum([group_count(g) | some g in category_groups; category_of(g) == c])

# Rule: O622-REPORT-01 (deregistered annual-average head count per category)
deregistered_count(c) := sum([d.average_count |
	some d in object.get(app, "deregistrations", [])
	d.measure_category == c
])

# Rule: O622-PREM-GVE-01 / O622-REPORT-03 / O622-SUP-UNK-04 (applied head count minus deregistered head count)
premium_head_count(c) := max([0, category_head_count(c) - deregistered_count(c)])

# Rule: O622-PREM-GVE-01 / O622-GVE-01
category_gve[c] := r2(premium_head_count(c) * measure_categories[c].gve_per_head) if {
	some c in active_categories
}

participating_gve := r2(sum([v | some v in category_gve]))

# Rule: O622-ELIG-01 (at least 2.00 GVE over all applied categories)
min_participation_met if participating_gve >= params.min_participation_gve

measure_applied if count(active_categories) > 0

# Rule: O622-CONTRACT-03 / O622-GEN-ACCESS-01 (access condition not met: no valid contract for the year)
violations contains {
	"rule_id": "O622-ELIG-01",
	"severity": "access_condition",
	"message": sprintf("Participating GVE %v below minimum of %v GVE; the contract for the measure lapses", [participating_gve, params.min_participation_gve]),
} if {
	measure_applied
	not min_participation_met
}

# Rule: O622-APP-07 (category without any premium-eligible animal lapses automatically)
category_contract_lapsed contains c if {
	some c in active_categories
	premium_head_count(c) <= 0
}

violations contains {
	"rule_id": "O622-APP-07",
	"severity": "contract_lapse",
	"message": sprintf("No premium-eligible animal in category %v; the category contract lapses and a new timely application is required", [c]),
} if {
	some c in category_contract_lapsed
}

# Tierwohl – Schweinehaltung (o6_22): stall housing conditions (definitions,
# group housing, lying area, litter, enrichment material, space allowance).
package oepul.o6_22

# Rule: O622-FAT-SPACE-02 (weight class via group average; half-open class boundaries, see notes/assumptions.md)
space_weight(g) := g.average_live_weight_kg if {
	is_number(object.get(g, "average_live_weight_kg", null))
} else := tierliste[g.tierliste_category].fallback_space_weight_kg

weight_in_class(_, row) if row.upper_kg == null

weight_in_class(w, row) if {
	row.upper_kg != null
	row.upper_inclusive == true
	w <= row.upper_kg
}

weight_in_class(w, row) if {
	row.upper_kg != null
	row.upper_inclusive == false
	w < row.upper_kg
}

# Rule: O622-FAT-SPACE-01 (minimum area table for Ferkel, Jung- und Mastschweine)
fattening_requirement(w) := space.fattening[min({i | some i, row in space.fattening; weight_in_class(w, row)})]

# Rule: O622-SOW-SPACE-01 (minimum area table for Zuchtsauen and gedeckte Jungsauen)
sow_requirement(sow_type) := row if {
	some row in space.sows
	row.sow_type == sow_type
}

space_requirement(g) := fattening_requirement(space_weight(g)) if {
	not is_sow_group(g)
}

space_requirement(g) := sow_requirement(tierliste[g.tierliste_category].sow_type) if {
	is_sow_group(g)
}

# Rule: O622-FAT-SPACE-01 / O622-SOW-SPACE-01 (required usable total area in the compartment)
required_total_area(g) := r2(g.animal_count * space_requirement(g).total_area_m2_per_animal)

# Rule: O622-FAT-LYING-01 (littered lying area >= 40 % of the required usable total area)
required_littered_lying_area(g) := r2(space.fattening_min_littered_lying_share * required_total_area(g)) if {
	not is_sow_group(g)
}

# Rule: O622-SOW-SPACE-01 (lying area 1.30 m² per Zuchtsau / 0.95 m² per gedeckte Jungsau)
required_littered_lying_area(g) := r2(g.animal_count * space_requirement(g).lying_area_m2_per_animal) if {
	is_sow_group(g)
}

# Rule: O622-DEF-AREA-01 (usable total area = stall plus paved outdoor run with permanent access)
usable_total_area(g) := stall(g).stall_area_m2 + stall(g).paved_outdoor_run_area_m2 if {
	stall(g).outdoor_run_permanently_accessible == true
	is_number(object.get(stall(g), "paved_outdoor_run_area_m2", null))
} else := stall(g).stall_area_m2

# Rule: O622-DOC-SKETCH-03 (maximum occupancy of a compartment computed from the space table)
max_animals_in_compartment(area_m2, weight_kg) := floor((area_m2 + 0.000001) / fattening_requirement(weight_kg).total_area_m2_per_animal)

max_sows_in_compartment(area_m2, sow_type) := floor((area_m2 + 0.000001) / sow_requirement(sow_type).total_area_m2_per_animal)

# Rule: O622-DEF-STALL-01 (closed stall definition)
stall_definition_failure(s) if {
	object.get(s, "is_open_stall", false) != true
	s.enclosed_sides < params.stall_min_enclosed_sides
}

stall_definition_failure(s) if s.lying_area_roofed == false

stall_definition_failure(s) if {
	object.get(s, "is_open_stall", false) != true
	s.floor_paved == false
}

stall_definition_failure(s) if {
	object.get(s, "is_open_stall", false) != true
	s.liquid_manure_container == false
}

# Rule: O622-DEF-STALL-02 (open stall systems: roof over lying area, liquid-tight floor, seepage drain)
stall_definition_failure(s) if {
	s.is_open_stall == true
	s.floor_liquid_tight == false
}

stall_definition_failure(s) if {
	s.is_open_stall == true
	s.seepage_drain_to_pit == false
}

# Rule: O622-STALL-GROUP-02 (single housing of sick/injured animals up to 10 days on litter)
single_housing(g) := object.get(welfare(g), "single_housing", {})

permitted_single_housing(g) if {
	sh := single_housing(g)
	sh.reason == "illness_or_injury"
	sh.max_days <= params.single_housing_max_days
	sh.littered == true
}

enrichment_codes := {row.code | some row in lists.enrichment_materials}

littered_with_straw_or_hay(g) if stall(g).bedding_type == "straw"

littered_with_straw_or_hay(g) if object.get(stall(g), "litter_material", null) in {"straw", "hay"}

# Rule: O622-STALL-ENRICH-01 (enrichment material grass/straw/hay at all times)
enrichment_ok(g) if {
	littered_with_straw_or_hay(g)
	object.get(stall(g), "minimal_litter", false) != true
}

enrichment_ok(g) if object.get(stall(g), "enrichment_material", "none") in enrichment_codes

enrichment_known(g) if object.get(stall(g), "bedding_type", "unknown") != "unknown"

enrichment_known(g) if object.get(stall(g), "enrichment_material", "unknown") != "unknown"

stall_groups := {i: g | some i, g in participating_groups; stall_kept(g)}

# ---- group issues: animals affected must be deregistered (O622-REPORT-01) ----

# Rule: O622-STALL-GROUP-01
group_issues contains {"group": i, "rule_id": "O622-STALL-GROUP-01", "reason": "no_group_housing"} if {
	some i, g in stall_groups
	welfare(g).group_housing == false
	not permitted_single_housing(g)
}

# Rule: O622-STALL-GROUP-03
group_issues contains {"group": i, "rule_id": "O622-STALL-GROUP-03", "reason": "single_housing_over_10_days"} if {
	some i, g in stall_groups
	single_housing(g).max_days > params.single_housing_max_days
}

# Rule: O622-STALL-GROUP-02
group_issues contains {"group": i, "rule_id": "O622-STALL-GROUP-02", "reason": "single_housing_not_littered"} if {
	some i, g in stall_groups
	single_housing(g).reason == "illness_or_injury"
	single_housing(g).littered == false
}

# Rule: O622-STALL-GROUP-02 (single housing only for health reasons)
group_issues contains {"group": i, "rule_id": "O622-STALL-GROUP-02", "reason": "single_housing_without_health_reason"} if {
	some i, g in stall_groups
	single_housing(g).reason == "other"
}

# Rule: O622-STALL-01 (littered systems only)
group_issues contains {"group": i, "rule_id": "O622-STALL-01", "reason": "not_littered"} if {
	some i, g in stall_groups
	stall(g).bedding_type == "none"
}

# Rule: O622-STALL-LYING-01 (closed lying area, fully slatted floors do not qualify)
group_issues contains {"group": i, "rule_id": "O622-STALL-LYING-01", "reason": "full_slatted_floor"} if {
	some i, g in stall_groups
	stall(g).floor_type == "full_slatted"
}

# Rule: O622-STALL-LYING-01 (perforation of lying area max. 5 %)
group_issues contains {"group": i, "rule_id": "O622-STALL-LYING-01", "reason": "lying_area_perforation_above_5_percent"} if {
	some i, g in stall_groups
	stall(g).lying_area_perforation_percent > space.max_lying_area_perforation_percent
}

# Rule: O622-STALL-LYING-02 (dry littered lying area)
group_issues contains {"group": i, "rule_id": "O622-STALL-LYING-02", "reason": "lying_area_not_dry"} if {
	some i, g in stall_groups
	stall(g).lying_area_dry == false
}

# Rule: O622-STALL-ENRICH-01
group_issues contains {"group": i, "rule_id": "O622-STALL-ENRICH-01", "reason": "insufficient_enrichment_material"} if {
	some i, g in stall_groups
	enrichment_known(g)
	not enrichment_ok(g)
}

# Rule: O622-SPACE-TOTAL / O622-FAT-SPACE-01 / O622-FAT-SPACE-03 / O622-SOW-SPACE-01 / O622-DEF-STALL-03
group_issues contains {"group": i, "rule_id": "O622-SPACE-TOTAL", "reason": "insufficient_usable_total_area"} if {
	some i, g in stall_groups
	usable_total_area(g) < required_total_area(g)
}

# Rule: O622-SPACE-LYING / O622-FAT-LYING-01 / O622-SOW-SPACE-01 / O622-STALL-LYING-03
group_issues contains {"group": i, "rule_id": "O622-SPACE-LYING", "reason": "insufficient_littered_lying_area"} if {
	some i, g in stall_groups
	stall(g).lying_area_m2 < required_littered_lying_area(g)
}

# Rule: O622-DEF-STALL-01 / O622-DEF-STALL-02
group_issues contains {"group": i, "rule_id": "O622-DEF-STALL-01", "reason": "stall_definition_not_met"} if {
	some i, g in stall_groups
	stall_definition_failure(stall(g))
}

# Rule: O622-FAT-ALL-02 / O622-SOW-ALL-02 / O622-CONTRACT-04 / O622-GEN-DURATION-01 (continuous compliance over the whole holding period)
group_issues contains {"group": i, "rule_id": "O622-FAT-ALL-02", "reason": "not_compliant_throughout_holding_period"} if {
	some i, g in participating_groups
	welfare(g).compliant_throughout_holding_period == false
}

# Rule: O622-STALL-GROUP-04 (documentation of illness and duration of single housing)
violations contains {
	"rule_id": "O622-STALL-GROUP-04",
	"severity": "obligation",
	"message": sprintf("Group %v: illness/injury and duration of single housing are not documented", [i]),
} if {
	some i, g in stall_groups
	single_housing(g).reason == "illness_or_injury"
	single_housing(g).documented == false
}

# Missing key inputs are surfaced instead of being treated as compliant.
missing_inputs contains sprintf("livestock.species_groups[%v].housing.stall.stall_area_m2", [i]) if {
	some i, g in stall_groups
	not is_number(object.get(stall(g), "stall_area_m2", null))
}

missing_inputs contains sprintf("livestock.species_groups[%v].housing.stall.lying_area_m2", [i]) if {
	some i, g in stall_groups
	not is_number(object.get(stall(g), "lying_area_m2", null))
}

missing_inputs contains sprintf("livestock.species_groups[%v].pig_welfare.group_housing", [i]) if {
	some i, g in stall_groups
	not is_boolean(object.get(welfare(g), "group_housing", null))
}

# Rule: O622-GROUP-SOW-01 / O622-GROUP-SOW-02 (group-housing window for sows under the 1. THVO)
sow_group_housing_period(regime) := row if {
	some row in params.sow_group_housing_periods
	row.regime == regime
}

# Rule: O622-GROUP-SOW-02 (transitional window only for existing stalls, only until 2033 and only
# if the requirement cannot be met without construction work; otherwise the 10-day window applies)
applicable_sow_regime(existing_stall_without_rebuild, achievable_without_construction, y) := "uebergang_bestand_bis_2033" if {
	existing_stall_without_rebuild == true
	achievable_without_construction == false
	y <= sow_group_housing_period("uebergang_bestand_bis_2033").valid_until_year
} else := "neu_oder_umbau_seit_2013"

# Rule: O622-GROUP-SOW-01 / O622-GROUP-SOW-03 / O622-GROUP-SOW-04 (group housing and the other
# conditions (litter, space) are only required inside this window; applies also below 10 sows)
sow_group_housing_required(days_after_mating, days_before_expected_farrowing, regime) if {
	p := sow_group_housing_period(regime)
	days_after_mating >= p.start_days_after_mating
	days_before_expected_farrowing >= p.end_days_before_expected_farrowing
}

# Tierwohl – Schweinehaltung (o6_22): optional supplements (undocked tails,
# GMO-free European protein feed, solid manure composting).
package oepul.o6_22

# ---- Zuschlag unkupierte Tiere ----

# Rule: O622-SUP-UNK-01 / O622-SUP-UNK-02 (all participating animals of the category undocked all year)
violations contains {
	"rule_id": "O622-SUP-UNK-02",
	"severity": "supplement_obligation",
	"message": sprintf("Undocked-tail supplement for %v: participating group %v has docked tails", [c, i]),
} if {
	some i, g in participating_groups
	c := category_of(g)
	supplement_active_for("unkupiert", c)
	not i in noncompliant_groups
	g.tail_docked == true
}

# ---- Zuschlag GVO-freie Eiweißfuttermittel ----

gvo := object.get(app, "gvo_free_protein_feed", {})

gvo_supplement_active if {
	some c in active_categories
	supplement_active_for("gvo_frei_eiweiss", c)
}

# Rule: O622-SUP-GVO-01 (all animals on the farm, whole calendar year)
violations contains {
	"rule_id": "O622-SUP-GVO-01",
	"severity": "supplement_obligation",
	"message": "GMO-free supplement: all protein feed for all animals on the farm must be GMO-free and of European origin for the whole calendar year",
} if {
	gvo_supplement_active
	gvo.all_protein_feed_gvo_free_european == false
}

# Rule: O622-SUP-GVO-01 (no storage or feeding of non-compliant protein feed, incl. old stocks and other species)
violations contains {
	"rule_id": "O622-SUP-GVO-01",
	"severity": "supplement_obligation",
	"message": "GMO-free supplement: non-compliant protein feed is stored or fed on the farm",
} if {
	gvo_supplement_active
	gvo.non_compliant_protein_feed_stored_or_fed == true
}

# Rule: O622-SUP-GVO-03 (proof of European origin and GMO freedom for purchased protein feed)
violations contains {
	"rule_id": "O622-SUP-GVO-03",
	"severity": "supplement_obligation",
	"message": "GMO-free supplement: proofs (delivery notes, invoices, feed recipes) for purchased protein feed are missing",
} if {
	gvo_supplement_active
	gvo.purchase_proofs_available == false
}

# Rule: O622-SUP-GVO-02 (protein feed definition: > 20 % crude protein in dry matter, roughage excluded)
is_protein_feed(feed) if {
	feed.is_roughage != true
	feed.crude_protein_percent_dm > params.protein_feed_min_crude_protein_percent_dm_exclusive
}

# Rule: O622-SUP-GVO-03 ('European' means the continent of Europe, not only the EU)
feed_origin_ok(feed) if feed.origin_continent == "europe"

# ---- Zuschlag Festmistkompostierung ----

composting := object.get(app, "solid_manure_composting", {})

composting_supplement_active if {
	year >= params.festmist_supplement_first_year
	some c in active_categories
	supplement_active_for("festmistkompostierung", c)
}

equipment := {row.code: row | some row in lists.compost_turning_equipment}

# Rule: O622-SUP-COMP-02 / O622-SUP-COMP-03 (turning equipment)
equipment_ok(w) if {
	row := equipment[w.turning_equipment]
	row.eligible == true
	row.requires_complete_turning_proof == false
	w.equipment_owned_or_use_documented == true
}

equipment_ok(w) if {
	row := equipment[w.turning_equipment]
	row.eligible == true
	row.requires_complete_turning_proof == true
	w.complete_turning == true
	w.equipment_owned_or_use_documented == true
}

# Rule: O622-SUP-COMP-01 (turned at least twice, >= 14 days apart)
turning_ok(w) if {
	count(w.turn_dates) >= params.compost_min_turn_count
	some d1 in w.turn_dates
	some d2 in w.turn_dates
	days_between(d1, d2) >= params.compost_min_turn_interval_days
}

# Rule: O622-SUP-COMP-01 / O622-SUP-COMP-02 / O622-SUP-COMP-03
windrow_ok(w) if {
	w.method == "turned"
	turning_ok(w)
	equipment_ok(w)
}

# Rule: O622-SUP-COMP-04 (mixture or layering with plant material, no turning required)
windrow_ok(w) if {
	w.method == "mixed_or_layered"
	w.plant_material_share_percent > 0
	object.get(w, "straw_rich_manure_only", false) != true
}

# Rule: O622-SUP-COMP-05 (no turner: substantial plant material plus composting process)
windrow_ok(w) if {
	w.method == "unturned_with_additives"
	w.plant_material_share_percent > 0
	w.composting_process_applied == true
	object.get(w, "straw_rich_manure_only", false) != true
}

violations contains {
	"rule_id": "O622-SUP-COMP-01",
	"severity": "supplement_obligation",
	"message": sprintf("Composting supplement: windrow %v does not meet the composting requirements", [object.get(w, "windrow_id", idx)]),
} if {
	composting_supplement_active
	some idx, w in object.get(composting, "windrows", [])
	not windrow_ok(w)
}

# Rule: O622-SUP-COMP-01 (entire solid manure of the farm, all species)
violations contains {
	"rule_id": "O622-SUP-COMP-01",
	"severity": "supplement_obligation",
	"message": "Composting supplement: the entire solid manure of the farm must be composted in windrows on the farm",
} if {
	composting_supplement_active
	composting.all_solid_manure_composted_on_farm == false
}

violations contains {
	"rule_id": "O622-SUP-COMP-01",
	"severity": "supplement_obligation",
	"message": "Composting supplement: no compost windrow recorded",
} if {
	composting_supplement_active
	count(object.get(composting, "windrows", [])) == 0
}

# Rule: O622-SUP-COMP-06 (documentation of set-up, turning, spreading/transfer)
violations contains {
	"rule_id": "O622-SUP-COMP-06",
	"severity": "supplement_obligation",
	"message": "Composting supplement: documentation of windrow set-up, turning and spreading/transfer is incomplete",
} if {
	composting_supplement_active
	composting.documentation_complete == false
}

# Rule: O622-SUP-COMP-07 (Nitrate Action Programme Regulation for windrows)
violations contains {
	"rule_id": "O622-SUP-COMP-07",
	"severity": "legal_obligation",
	"message": "Composting supplement: compost windrows must comply with the Nitrat-Aktionsprogramm-Verordnung",
} if {
	composting_supplement_active
	composting.nitrate_action_programme_compliant == false
}

# Rule: O622-SUP-COMP-08 (no supplement for compost barns)
composting_supplement_excluded if {
	composting_supplement_active
	composting.compost_stall_system == true
}

violations contains {
	"rule_id": "O622-SUP-COMP-08",
	"severity": "supplement_not_grantable",
	"message": "Composting supplement cannot be granted for compost barns (Kompostställe)",
} if {
	composting_supplement_excluded
}

# Advisory: 'nennenswertes Ausmaß (z. B. 50:50)' is only given as an example (see notes/assumptions.md).
advisories contains sprintf("Windrow %v: plant material share %v %% is below the 50:50 example ratio", [object.get(w, "windrow_id", idx), w.plant_material_share_percent]) if {
	composting_supplement_active
	some idx, w in object.get(composting, "windrows", [])
	w.method == "unturned_with_additives"
	w.plant_material_share_percent < 50
}

